// Reads all schedule JSON files and writes schedules_import.sql
// Usage: node scripts/import-schedules.js
// Then:  wrangler d1 execute gds-schedule-tracker --remote --file=schedules_import.sql

const fs   = require('fs');
const path = require('path');

const SCHED_DIR = path.join(__dirname, '..', 'schedules');
const OUT_FILE  = path.join(__dirname, '..', 'schedules_import.sql');

const files = fs.readdirSync(SCHED_DIR).filter(f => f.endsWith('.json'));

const lines = [
  '-- Auto-generated by scripts/import-schedules.js',
  '-- Imports all schedule JSON files into D1',
  '',
];

let count = 0;
for (const file of files) {
  const raw  = JSON.parse(fs.readFileSync(path.join(SCHED_DIR, file), 'utf8'));
  const meta = raw._meta || {};

  // name: prefer _meta, fall back to parsing filename
  const name = (meta.name || '').trim() ||
    file.replace('_TeamSched.json', '').replace(/_/g, ' ').trim();

  if (!name) { console.warn(`Skipping ${file} — no name`); continue; }

  // strip _meta before storing schedule data
  const data = Object.fromEntries(Object.entries(raw).filter(([k]) => k !== '_meta'));

  // escape single quotes for SQL
  const escape = s => s.replace(/'/g, "''");

  const dataJson    = escape(JSON.stringify(data));
  const team        = escape(meta.team     || '');
  const position    = escape(meta.position || '');
  const lastSaved   = escape(meta.lastSaved || '');

  lines.push(
    `INSERT INTO schedules (name, data, team, position, last_saved)` +
    ` VALUES ('${escape(name)}', '${dataJson}', '${team}', '${position}', '${lastSaved}')` +
    ` ON CONFLICT(name) DO UPDATE SET` +
    ` data = excluded.data, team = excluded.team,` +
    ` position = excluded.position, last_saved = excluded.last_saved;`
  );
  count++;
}

fs.writeFileSync(OUT_FILE, lines.join('\n') + '\n');
console.log(`✓ Written ${count} schedules → schedules_import.sql`);
console.log(`  Run: wrangler d1 execute gds-schedule-tracker --remote --file=schedules_import.sql`);
